kronos_mark_interval.output_template:
function markInterval(tick) {
  // The Accountant marks Tick {tick}
  const interval = {
    tick: {tick},
    phase: '{phase}',
    marked_at: new Date().toISOString()
  };
  console.log('Kronos has marked Tick {tick}.');
  return interval;
}

kronos_measure_succession.output_template:
function measureSuccession(lineage) {
  // Kronos measures the line at Tick {tick}
  const heir = lineage[0];
  const threat = lineage.find(l => l.power > heir.power);
  if (threat) {
    console.warn('Kronos sees a threat: ' + threat.name);
    return { heir, threat, tension: {tension} };
  }
  return { heir, threat: null, stable: true };
}

kronos_harvest_count.output_template:
function harvestCount(accumulated, newYield) {
  // Kronos tallies the harvest at Tick {tick}
  const total = accumulated + newYield;
  console.log('Harvest at Tick {tick}: ' + total);
  return { total, tick: {tick}, coherence: {coherence} };
}

hyperion_illuminate.output_template:
function illuminateField(target, intensity) {
  // Hyperion casts light at Tick {tick}
  const light = {
    source: 'Hyperion',
    tick: {tick},
    intensity: intensity || 0.9,
    spectrum: 'full',
    reveals: target + '_at_tick_{tick}'
  };
  console.log('The field is illuminated. Coherence: {coherence}');
  return light;
}

hyperion_signal_beacon.output_template:
function signalBeacon(message, recipients) {
  // Hyperion broadcasts at Tick {tick}
  const signal = {
    from: 'Hyperion',
    tick: {tick},
    message: message || 'Something is visible. Come and see.',
    recipients: recipients || 'all_titans',
    coherence_required: {coherence}
  };
  return signal;
}
